class Solution:
    def unique_paths(self, m: int, n: int) -> int:
        """Count unique paths in m x n grid from top-left to bottom-right."""
        # Initialize 2D DP array
        dp = [[0] * n for _ in range(m)]

        # Base case: first row - only one way (move right)
        for i in range(n):
            dp[0][i] = 1

        # Base case: first column - only one way (move down)
        for j in range(m):
            dp[j][0] = 1

        # Fill DP table using recurrence relation
        for i in range(1, m):
            for j in range(1, n):
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

        return dp[m - 1][n - 1]
